import{_ as p,a0 as l,w as o,s as r,ao as d,I as n,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"通过 Linux 命令行连接 Wifi | LCTT x X-CMD","titleTemplate":false,"description":"通过 Linux 命令行连接 Wifi | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过 Linux 命令行连接 Wifi | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过 Linux 命令行连接 Wifi | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171002 Connect To Wifi From The Linux Command Line","title":"通过 Linux 命令行连接 Wifi","tag":"201801","desc":""},"relativePath":"201801/20171002 Connect To Wifi From The Linux Command Line.md","filePath":"[post].md"}'),h={name:"201801/20171002 Connect To Wifi From The Linux Command Line.md"};function c(u,i,g,k,f,b){const s=l("Link");return o(),r("div",null,[i[13]||(i[13]=d(`<h1 id="通过-linux-命令行连接-wifi" tabindex="-1">通过 Linux 命令行连接 Wifi <a class="header-anchor" href="#通过-linux-命令行连接-wifi" aria-label="Permalink to “通过 Linux 命令行连接 Wifi”">​</a></h1><p>目标：仅使用命令行工具来配置 WiFi</p><p>发行版：适用主流的那些发行版</p><p>要求：安装了无线网卡的 Linux 并且拥有 root 权限。</p><p>难度：简单</p><p>约定：</p><ul><li><code>#</code> - 需要使用 root 权限来执行指定命令，可以直接使用 root 用户来执行，也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 可以使用普通用户来执行指定命令</li></ul><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p>许多人喜欢用图形化的工具来管理电脑，但也有很多人不喜欢这样做。如果你比较喜欢命令行工具，管理 WiFi 会是件很痛苦的事情。然而，事情本不该如此。</p><p>wpa_supplicant 可以作为命令行工具来用。使用一个简单的配置文件就可以很容易设置号 WiFi。</p><h3 id="扫描网络" tabindex="-1">扫描网络 <a class="header-anchor" href="#扫描网络" aria-label="Permalink to “扫描网络”">​</a></h3><p>若你已经知道了网络的信息，就可以跳过这一步。如果不了解的话，则这是一个找出网络信息的好方法。</p><p>wpa_supplicant 中有一个工具叫做 <code>wpa_cli</code>，它提供了一个命令行接口来管理你的 WiFi 连接。事实上你可以用它来设置任何东西，但是设置一个配置文件看起来要更容易一些。</p><p>使用 root 权限运行 <code>wpa_cli</code>，然后扫描网络。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wpa_cli</span></span>
<span class="line"><span>&gt; scan</span></span></code></pre></div><p>扫描过程要花上一点时间，并且会显示所在区域的那些网络。记住你想要连接的那个网络。然后输入 <code>quit</code> 退出。</p><h3 id="生成配置块并且加密你的密码" tabindex="-1">生成配置块并且加密你的密码 <a class="header-anchor" href="#生成配置块并且加密你的密码" aria-label="Permalink to “生成配置块并且加密你的密码”">​</a></h3><p>还有更方便的工具可以用来设置配置文件。它接受网络名称和密码作为参数，然后生成一个包含该网路配置块（其中的密码被加密处理了）的配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wpa_passphrase networkname password &gt; /etc/wpa_supplicant/wpa_supplicant.conf</span></span></code></pre></div><h3 id="裁剪你的配置" tabindex="-1">裁剪你的配置 <a class="header-anchor" href="#裁剪你的配置" aria-label="Permalink to “裁剪你的配置”">​</a></h3><p>现在你已经有了一个配置文件了，这个配置文件就是 <code>/etc/wpa_supplicant/wpa_supplicant.conf</code>。其中的内容并不多，只有一个网络块，其中有网络名称和密码，不过你可以在此基础上对它进行修改。</p><p>用喜欢的编辑器打开该文件，首先删掉说明密码的那行注释。然后，将下面行加到配置最上方。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ctrl_interface=DIR=/var/run/wpa_supplicant GROUP=wheel</span></span></code></pre></div><p>这一行只是让 <code>wheel</code> 组中的用户可以管理 wpa_supplicant。这会方便很多。</p><p>其他的内容则添加到网络块中。</p><p>如果你要连接到一个隐藏网络，你可以添加下面行来通知 wpa_supplicant 先扫描该网络。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scan_ssid=1</span></span></code></pre></div><p>下一步，设置协议以及密钥管理方面的配置。下面这些是 WPA2 相关的配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>proto=RSN</span></span>
<span class="line"><span>key_mgmt=WPA-PSK</span></span></code></pre></div><p><code>group</code> 和 <code>pairwise</code> 配置告诉 wpa_supplicant 你是否使用了 CCMP、TKIP，或者两者都用到了。为了安全考虑，你应该只用 CCMP。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>group=CCMP</span></span>
<span class="line"><span>pairwise=CCMP</span></span></code></pre></div><p>最后，设置网络优先级。越高的值越会优先连接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>priority=10</span></span></code></pre></div><p><img src="https://linuxconfig.org/images/wpa-cli-config.jpg" alt="Complete WPA_Supplicant Settings"></p><p>保存配置然后重启 wpa_supplicant 来让改动生效。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>当然，该方法并不是用于即时配置无线网络的最好方法，但对于定期连接的网络来说，这种方法非常有效。</p><hr>`,38)),n("p",null,[i[1]||(i[1]=a("via: ",-1)),e(s,{href:"https://linuxconfig.org/connect-to-wifi-from-the-linux-command-line"},{default:t(()=>[...i[0]||(i[0]=[a("https://linuxconfig.org/connect-to-wifi-from-the-linux-command-line",-1)])]),_:1})]),n("p",null,[i[5]||(i[5]=a("作者：",-1)),e(s,{href:"https://linuxconfig.org"},{default:t(()=>[...i[2]||(i[2]=[a("Nick Congleton",-1)])]),_:1}),i[6]||(i[6]=a(" 译者：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[3]||(i[3]=[a("lujun9972",-1)])]),_:1}),i[7]||(i[7]=a(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:t(()=>[...i[4]||(i[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[i[10]||(i[10]=a("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[8]||(i[8]=[a("LCTT",-1)])]),_:1}),i[11]||(i[11]=a(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:t(()=>[...i[9]||(i[9]=[a("Linux中国",-1)])]),_:1}),i[12]||(i[12]=a(" 荣誉推出",-1))])])}const T=p(h,[["render",c]]);export{x as __pageData,T as default};
